SELECT t_sales_bidding.quantity, t_the_order.product_category_name AS productCategoryName, t_order_line.id, t_order_line.`status`, t_order_line.order_no AS orderNo, t_listed.materiel_no AS materielNo, t_listed.materiel_name AS materielName, t_sales_bidding.`status`, t_order_line.order_line_no AS orderLineNo, t_order_line.listed_no AS listedNo, t_order_line.order_submission_price AS orderSubmissionPrice, t_order_line.order_submission_quantity AS orderSubmissionQuantity, t_order_line.transaction_price AS transactionPrice, t_order_line.turnover_quantity AS turnoverQuantity, t_order_line.freight, t_order_line.benchmark_price AS benchmarkPrice, t_order_line.remark, t_order_line.order_start_time AS orderStartTime, t_order_line.order_end_time AS orderEndTime, t_order_line.order_approval_time AS orderApprovalTime, t_order_line.dd_warn_day AS ddWarnDay, t_order_line.customer_no AS customerNo, t_order_line.customer_name AS customerName, t_order_line.workflowid AS workflowid, t_order_line.shbz, t_order_line.company_no AS companyNo, t_order_line.company_name AS companyName, t_order_line.order_type AS orderType FROM t_order_line left join t_listed on t_order_line.listed_no = t_listed.listed_no left join t_sales_bidding on t_listed.listed_no = t_sales_bidding.tender_number left join t_the_order on t_order_line.order_no = t_the_order.order_no WHERE t_order_line.is_deleted = 0 AND t_order_line.listed_no =#{entity.listedNo}
AND t_order_line.company_name LIKE CONCAT('%', #{entity.companyName}, '%')
ORDER BY t_order_line.gmt_modified DESC

